using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Linq;using System.Security.Cryptography;
[InitializeOnLoad]public static class HunterSettlementIntegration {
 const string Out="Evidence/hunter-settlement-20261030/";
 static HunterSettlementIntegration(){EditorApplication.delayCall+=Build;EditorApplication.delayCall+=FinishWhenReady;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode)EditorApplication.delayCall+=FinishWhenReady;};}
 static string Hash(string p){using(var h=SHA256.Create())return System.BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 [MenuItem("Vampire Demo/Hunter/Integrate Settlement - Slow Roll")]
 static void Build(){if(EditorApplication.isPlayingOrWillChangePlaymode||File.Exists(Out+"setup.txt"))return;Directory.CreateDirectory(Out);string source="Assets/Demo/Scenes/PrologueSettlement.unity";string before=Hash(source);var scene=EditorSceneManager.OpenScene(source);string dest=AssetDatabase.GenerateUniqueAssetPath("Assets/Demo/Scenes/PrologueSettlement_Hunter.unity");EditorSceneManager.SaveScene(scene,dest);
 var p=Object.FindObjectOfType<DemoMovement>();if(!p)throw new System.Exception("No settlement player");string old="duration="+p.dodgeDuration+" distance="+p.dodgeDistance+" invulnerability="+p.dodgeInvulnerability;foreach(string name in new[]{"Hunter body","Hunter head"}){var t=p.transform.Find(name);if(t){var r=t.GetComponent<Renderer>();if(r)r.enabled=false;}}
 var template=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Demo/Characters/Hunter/Hunter_PlayerCandidate.prefab");var a=template.GetComponentInChildren<Animator>(true);var model=a.transform;while(model.parent&&model.parent!=template.transform)model=model.parent;var visual=Object.Instantiate(model.gameObject,p.transform);visual.name="Hunter Visual";visual.transform.localPosition=Vector3.zero;visual.transform.localRotation=Quaternion.identity;
 foreach(var r in visual.GetComponentsInChildren<HunterReview>(true))Object.DestroyImmediate(r);var bridge=p.gameObject.AddComponent<HunterGameplayAnimator>();bridge.animator=visual.GetComponentInChildren<Animator>();bridge.animator.applyRootMotion=false;p.dodgeDuration=.8f;p.gameObject.AddComponent<HunterSettlementProbe>();
 string prefab=AssetDatabase.GenerateUniqueAssetPath("Assets/Demo/Characters/Hunter/Hunter_SettlementPlayer.prefab");PrefabUtility.SaveAsPrefabAsset(p.gameObject,prefab);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText(Out+"setup.txt","source="+source+"\nsourceBefore="+before+"\nsourceAfter="+Hash(source)+"\nscene="+dest+"\nprefab="+prefab+"\nbefore="+old+"\nafter duration="+p.dodgeDuration+" distance="+p.dodgeDistance+" invulnerability="+p.dodgeInvulnerability+"\n");}
 static void FinishWhenReady(){if(!File.Exists(Out+"playmode.txt")||File.Exists(Out+"final.txt")||EditorApplication.isPlayingOrWillChangePlaymode||UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!="PrologueSettlement_Hunter")return;Finish();}
 [MenuItem("Vampire Demo/Hunter/Finish Settlement Integration")]
 static void Finish(){if(EditorApplication.isPlaying)return;var p=Object.FindObjectOfType<HunterSettlementProbe>();if(p){var root=p.gameObject;Object.DestroyImmediate(p);var lamp=root.transform.Find("Carried lantern");if(lamp&&lamp.GetComponent<Renderer>())lamp.GetComponent<Renderer>().enabled=false;PrefabUtility.SaveAsPrefabAsset(root,"Assets/Demo/Characters/Hunter/Hunter_SettlementPlayer.prefab");EditorSceneManager.SaveScene(root.scene);}object[] counts={0,0,0};var t=typeof(Editor).Assembly.GetType("UnityEditor.LogEntries");t.GetMethod("GetCountsByType",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic).Invoke(null,counts);File.WriteAllText(Out+"final.txt","errors="+counts[0]+" warnings="+counts[1]+" logs="+counts[2]+"\nAutomatic test removed. Scene/prefab saved for manual play.");}
}
